struct ReadingBook {
    let title: String
    let pageCount: Int
    var pagesRead: Int
    var progressPercent: Double {
        guard pageCount > 0 else { return 0 }
        return Double(min(max(pagesRead, 0), pageCount)) / Double(pageCount) * 100
    }
}

let books = [ReadingBook(title: "Swift Guide", pageCount: 200, pagesRead: 40), ReadingBook(title: "Algorithms", pageCount: 100, pagesRead: 100)]
for book in books.sorted(by: { $0.title < $1.title }) {
    print("\(book.title): \(Int(book.progressPercent))%")
}
